using System;using System.IO;using System.IO.Compression;using System.Diagnostics;using System.Reflection;using System.Threading.Tasks;using System.Windows.Forms;using System.Drawing;using Microsoft.Win32;
class Installer:Form {
 Label info=new Label();Button install=new Button();CheckBox desktop=new CheckBox();ProgressBar progress=new ProgressBar();bool busy,installed;
 static string Root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","JARVIS");
 const string RegistryPath=@"Software\Microsoft\Windows\CurrentVersion\Uninstall\JARVIS";
 Installer(){Text="Установка JARVIS";ClientSize=new Size(510,230);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(10,19,34);ForeColor=Color.White;Font=new Font("Segoe UI",10);info.SetBounds(24,22,462,90);info.Text="JARVIS — персональный ассистент\n\nУстановка для текущего пользователя. Node.js и другие программы не требуются. При первом запуске укажите свой ключ Gemini.";desktop.Text="Создать ярлык на рабочем столе";desktop.Checked=true;desktop.SetBounds(24,126,450,26);progress.SetBounds(24,163,305,22);progress.Style=ProgressBarStyle.Marquee;progress.Visible=false;install.Text="Установить";install.SetBounds(345,162,140,34);install.Click+=async(s,e)=>{if(installed){Process.Start(Path.Combine(Root,"JARVIS.exe"));Close();}else await Install();};Controls.AddRange(new Control[]{info,desktop,progress,install});FormClosing+=(s,e)=>{if(busy)e.Cancel=true;};}
 static void Shortcut(string file,string target){Type type=Type.GetTypeFromProgID("WScript.Shell");object shell=Activator.CreateInstance(type),link=type.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{file});Type t=link.GetType();t.InvokeMember("TargetPath",BindingFlags.SetProperty,null,link,new object[]{target});t.InvokeMember("WorkingDirectory",BindingFlags.SetProperty,null,link,new object[]{Root});t.InvokeMember("IconLocation",BindingFlags.SetProperty,null,link,new object[]{target+",0"});t.InvokeMember("Save",BindingFlags.InvokeMethod,null,link,null);}
 async Task Install(){busy=true;install.Enabled=desktop.Enabled=false;progress.Visible=true;try{bool shortcut=desktop.Checked;await Task.Run(()=>{
  if(Directory.Exists(Root)&&!File.Exists(Path.Combine(Root,"jarvis-distribution.json"))&&Directory.GetFileSystemEntries(Root).Length>0)throw new Exception("Папка установки занята другими файлами.");Directory.CreateDirectory(Root);
  string stage=Path.Combine(Root,".install-"+Guid.NewGuid().ToString());Directory.CreateDirectory(stage);
  try{using(Stream stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip"))using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){
   string boundary=Path.GetFullPath(stage).TrimEnd('\\')+"\\";foreach(var entry in zip.Entries){string name=entry.FullName.Replace('\\','/');if(name.StartsWith("/")||name.Contains(":")||Array.IndexOf(name.Split('/'),"..")>=0)throw new Exception("Invalid archive path");string target=Path.GetFullPath(Path.Combine(stage,name));if(!target.StartsWith(boundary,StringComparison.OrdinalIgnoreCase))throw new Exception("Invalid install path");if(name.EndsWith("/")){Directory.CreateDirectory(target);continue;}Directory.CreateDirectory(Path.GetDirectoryName(target));entry.ExtractToFile(target,false);}
  }
  string version=File.ReadAllText(Path.Combine(stage,"current.txt")).Trim();if(!System.Text.RegularExpressions.Regex.IsMatch(version,@"^\d+\.\d+\.\d+$"))throw new Exception("Invalid application version");string pointer=Path.Combine(Root,"current.txt");if(File.Exists(pointer)&&new Version(File.ReadAllText(pointer).Trim()).CompareTo(new Version(version))>=0)throw new Exception("Эта или более новая версия уже установлена. Откройте JARVIS из меню Пуск.");
  string destination=Path.Combine(Root,"versions",version);if(Directory.Exists(destination))throw new Exception("Папка этой версии уже существует. Используйте обновление в JARVIS.");Directory.CreateDirectory(Path.GetDirectoryName(destination));Directory.Move(Path.Combine(stage,"versions",version),destination);
  foreach(string file in Directory.GetFiles(stage)){if(Path.GetFileName(file)=="current.txt")continue;File.Copy(file,Path.Combine(Root,Path.GetFileName(file)),true);}
  string next=Path.Combine(Root,"current.next");File.WriteAllText(next,version);if(File.Exists(pointer))File.Replace(next,pointer,null);else File.Move(next,pointer);
  }finally{try{Directory.Delete(stage,true);}catch{}}

 });
  string launcher=Path.Combine(Root,"JARVIS.exe"),start=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"JARVIS.lnk");Shortcut(start,launcher);if(shortcut)Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"JARVIS.lnk"),launcher);
  using(var key=Registry.CurrentUser.CreateSubKey(RegistryPath)){key.SetValue("DisplayName","JARVIS");key.SetValue("DisplayIcon",launcher);key.SetValue("InstallLocation",Root);key.SetValue("UninstallString","\""+Path.Combine(Root,"Uninstall.exe")+"\"");key.SetValue("NoModify",1);key.SetValue("NoRepair",1);}
  busy=false;progress.Visible=false;info.Text="JARVIS установлен.\n\nУ каждого пользователя свои настройки и подключения.\nКлючи и переписки автора в установщик не входят.";desktop.Visible=false;install.Text="Запустить";install.Enabled=true;installed=true;
 }catch(Exception e){busy=false;progress.Visible=false;install.Enabled=desktop.Enabled=true;MessageBox.Show("Не удалось установить JARVIS. Если он запущен — выйдите через трей и повторите установку.\n\n"+e.Message,"JARVIS",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.Run(new Installer());}
}
